+	if err != nil {
+		t.Fatalf("Repositories.EditRelease returned error: %v", err)
+	}
+
+	if !strings.Contains(gotBody, `"make_latest":"true"`) {
+		t.Errorf("EditRelease request body = %q, want it to contain `\"make_latest\":\"true\"`", gotBody)
+	}
+	if !strings.Contains(gotBody, `"prerelease":false`) {
+		t.Errorf("EditRelease request body = %q, want it to contain `\"prerelease\":false` (preservation)", gotBody)
