+		fmt.Fprint(w, `{"id":1}`)
+	})
+
+	ctx := context.Background()
+	_, _, err := client.Repositories.EditRelease(ctx, "o", "r", 1, input)
+	if err != nil {
+		t.Fatalf("Repositories.EditRelease returned error: %v", err)
+	}
+
+	if !strings.Contains(gotBody, `"make_latest":"legacy"`) {
+		t.Errorf("EditRelease request body = %q, want it to contain `\"make_latest\":\"legacy\"`", gotBody)
+	}
+}
+
+func TestRepositoriesService_EditRelease_makeLatestOmittedWhenNil(t *testing.T) {
+	client, mux, _, teardown := setup()
+	defer teardown()
+
+
+	input := &RepositoryRelease{
+		Prerelease: Bool(false),
+	}
+
+	var gotBody string
+	mux.HandleFunc("/repos/o/r/releases/1", func(w http.ResponseWriter, r *http.Request) {
+		buf := new(bytes.Buffer)
+		buf.ReadFrom(r.Body)
+		gotBody = buf.String()
+		fmt.Fprint(w, `{"id":1}`)
+	})
+
+	ctx := context.Background()
+	_, _, err := client.Repositories.EditRelease(ctx, "o", "r", 1, input)
+	if err != nil {
+		t.Fatalf("Repositories.EditRelease returned error: %v", err)
+	}
+
+	if strings.Contains(gotBody, "make_latest") {
+		t.Errorf("EditRelease request body = %q, must not contain `make_latest` when unset", gotBody)
+	}
+}
+
+func TestRepositoryRelease_MakeLatest_field(t *testing.T) {
+
+	want := "legacy"
+	r := &RepositoryRelease{MakeLatest: &want}
+	if r.MakeLatest == nil || *r.MakeLatest != want {
+		t.Errorf("RepositoryRelease.MakeLatest pointer not set correctly")
+	}
+
+	data, err := json.Marshal(r)
+	if err != nil {
+		t.Fatalf("json.Marshal returned error: %v", err)
+	}
+	if !strings.Contains(string(data), `"make_latest":"legacy"`) {
+		t.Errorf("Marshalled RepositoryRelease = %s, want it to contain `\"make_latest\":\"legacy\"`", data)
+	}
+
+
+	var got RepositoryRelease
+	if err := json.Unmarshal([]byte(`{"make_latest":"true"}`), &got); err != nil {
+		t.Fatalf("json.Unmarshal returned error: %v", err)
+	}
+	if got.MakeLatest == nil || *got.MakeLatest != "true" {
+		t.Errorf("Unmarshalled RepositoryRelease.MakeLatest = %v, want pointer to \"true\"", got.MakeLatest)
+	}
+}
