@@ -298,5 +304,40 @@ generateRuleTests({
         `);
       },
     },
+    {
+      // Only role="presentation"/"none" are transparent — a plain element
+      // with no role still breaks the context chain and should error.
+      template: '<div role="tablist"><div><div role="tab">Item One</div></div></div>',
+      verifyResults(results) {
+        expect(results.length).toBe(1);
+        expect(results[0].rule).toBe('require-context-role');
+        expect(results[0].message).toMatch(/role of "tab"/);
+        expect(results[0].message).toMatch(/\[tablist\]/);
+        expect(results[0].source).toBe('role="tab"');
+      },
+    },
+    {
+      // tab nested through a transparent presentation parent into the
+      // WRONG context role (tree, not tablist) should still error.
+      template:
+        '<div role="tree"><div role="presentation"><div role="tab">Item One</div></div></div>',
+      verifyResults(results) {
+        expect(results.length).toBe(1);
+        expect(results[0].rule).toBe('require-context-role');
+        expect(results[0].message).toMatch(/role of "tab"/);
+        expect(results[0].source).toBe('role="tab"');
+      },
+    },
+    {
+      // listitem under a wrapper with no role (via presentation) lands at
+      // an unrelated context — still missing required parent.
+      template:
+        '<div role="tablist"><div role="presentation"><div role="listitem">Item One</div></div></div>',
+      verifyResults(results) {
+        expect(results.length).toBe(1);
+        expect(results[0].rule).toBe('require-context-role');
+        expect(results[0].message).toMatch(/role of "listitem"/);
+      },
+    },
   ],
 });
