+function getGraphWidgetWidths(monitoring: CustomMonitoring): number[] {
+  const rows = monitoring.widgets() as Row[];
+
+  const graphRow = rows[rows.length - 1];
+  return graphRow.widgets.map((w) => {
+    const json = w.toJson() as Array<{ width: number }>;
+    return json[0].width;
+  });
+}
+
+test("graphWidgetWidth overrides auto-calculated width for that metric group", () => {
+  const stack = new Stack();
+  const scope = new TestMonitoringScope(stack, "Scope");
+
+  const monitoring = new CustomMonitoring(scope, {
+    alarmFriendlyName: "DummyAlarmName",
+    humanReadableName: "DummyName",
+    metricGroups: [
+      {
+        title: "OverriddenGroup",
+        graphWidgetWidth: 8,
+        metrics: [
+          new Metric({ metricName: "DummyMetric1", namespace, dimensionsMap }),
+        ],
+      },
+    ],
+  });
+
+  const widths = getGraphWidgetWidths(monitoring);
+  expect(widths).toEqual([8]);
+});
+
+test("metric group without graphWidgetWidth uses auto-calculated default", () => {
+  const stack = new Stack();
+  const scope = new TestMonitoringScope(stack, "Scope");
+
+
+  const monitoring = new CustomMonitoring(scope, {
+    alarmFriendlyName: "DummyAlarmName",
+    humanReadableName: "DummyName",
+    metricGroups: [
+      {
+        title: "G1",
+        metrics: [
+          new Metric({ metricName: "M1", namespace, dimensionsMap }),
+        ],
+      },
+      {
+        title: "G2",
+        metrics: [
+          new Metric({ metricName: "M2", namespace, dimensionsMap }),
+        ],
+      },
+      {
+        title: "G3",
+        metrics: [
+          new Metric({ metricName: "M3", namespace, dimensionsMap }),
+        ],
+      },
+      {
+        title: "G4",
+        metrics: [
+          new Metric({ metricName: "M4", namespace, dimensionsMap }),
+        ],
+      },
+    ],
+  });
+
+  const widths = getGraphWidgetWidths(monitoring);
+  expect(widths).toEqual([6, 6, 6, 6]);
+});
+
+test("graphWidgetWidth allows distinct widths per metric group", () => {
+  const stack = new Stack();
+  const scope = new TestMonitoringScope(stack, "Scope");
+
+
+
+  const monitoring = new CustomMonitoring(scope, {
+    alarmFriendlyName: "DummyAlarmName",
+    humanReadableName: "DummyName",
+    metricGroups: [
+      {
+        title: "Wide",
+        graphWidgetWidth: 18,
+        metrics: [
+          new Metric({ metricName: "WideMetric", namespace, dimensionsMap }),
+        ],
+      },
+      {
+        title: "Narrow",
+        graphWidgetWidth: 4,
+        metrics: [
+          new Metric({ metricName: "NarrowMetric", namespace, dimensionsMap }),
+        ],
+      },
+      {
+        title: "Auto",
+        metrics: [
+          new Metric({ metricName: "AutoMetric", namespace, dimensionsMap }),
+        ],
+      },
+    ],
+  });
+
+  const widths = getGraphWidgetWidths(monitoring);
+  expect(widths).toEqual([18, 4, 8]);
+});
+
+test("graphWidgetWidth on metric group is reflected in dashboard body", () => {
+  const stack = new Stack();
+  const scope = new TestMonitoringScope(stack, "Scope");
+
+  const monitoring = new CustomMonitoring(scope, {
+    alarmFriendlyName: "DummyAlarmName",
+    humanReadableName: "DummyName",
+    metricGroups: [
+      {
+        title: "WidthExplicit",
+        graphWidgetWidth: 11,
+        metrics: [
+          new Metric({
+            metricName: "WidthExplicitMetric",
+            namespace,
+            dimensionsMap,
+          }),
+        ],
+      },
+    ],
+  });
+
+  addMonitoringDashboardsToStack(stack, monitoring);
+  const template = Template.fromStack(stack);
+  const dashboards = template.findResources("AWS::CloudWatch::Dashboard");
+  const bodies = Object.values(dashboards).map(
+    (r: any) => r.Properties.DashboardBody
+  );
+
+
+  const flatten = (body: any): string => {
+    if (typeof body === "string") return body;
+    if (body && body["Fn::Join"]) {
+      const parts = body["Fn::Join"][1] as any[];
+      return parts.map(flatten).join("");
+    }
+    return "";
+  };
+  const joined = bodies.map(flatten).join("\n");
+  expect(joined).toMatch(/"type":"metric","width":11,/);
+
+
+  expect(joined).not.toMatch(/"type":"metric","width":24,/);
+});
+
+test("graphWidgetWidth on a metric group with anomaly detection widget is applied", () => {
+  const stack = new Stack();
+  const scope = new TestMonitoringScope(stack, "Scope");
+
+  const monitoring = new CustomMonitoring(scope, {
+    alarmFriendlyName: "AnomalyAlarmName",
+    metricGroups: [
+      {
+        title: "AnomalyGroupWithWidth",
+        graphWidgetWidth: 9,
+        metrics: [
+          {
+            metric: new MetricFactory({
+              globalDefaults: { namespace: "AnomalyNamespace" },
+            }).createMetricAnomalyDetection(
+              new Metric({
+                metricName: "AnomalyMetric",
+                namespace,
+                dimensionsMap,
+              }),
+              2,
+              "AnomalyLabel",
+              "blue",
+              "expression"
+            ),
+            alarmFriendlyName: "AnomalyMetricAlarm",
+            anomalyDetectionStandardDeviationToRender: 2,
+          },
+        ],
+      },
+    ],
+  });
+
+  const widths = getGraphWidgetWidths(monitoring);
+  expect(widths).toEqual([9]);
+});
