diff --git a/usercase-test-coderl/alias_batching_test.go b/usercase-test-coderl/alias_batching_test.go
new file mode 100644
--- /dev/null
+++ b/usercase-test-coderl/alias_batching_test.go
@@ -0,0 +1,448 @@
+package usercase_test_coderl
+
+import (
+	"context"
+	"encoding/json"
+	"fmt"
+	"io"
+	"net/http"
+	"net/http/httptest"
+	"net/url"
+	"os"
+	"reflect"
+	"runtime"
+	"strings"
+	"testing"
+
+	elastic "github.com/olivere/elastic/v7"
+)
+
+
+
+
+
+
+
+func mustMarshalAction(t *testing.T, action elastic.AliasAction) string {
+	t.Helper()
+	src, err := action.Source()
+	if err != nil {
+		t.Fatalf("Source returned error: %v", err)
+	}
+	b, err := json.Marshal(src)
+	if err != nil {
+		t.Fatalf("marshal Source: %v", err)
+	}
+	return string(b)
+}
+
+func assertJSONEqual(t *testing.T, name string, got string, want string) {
+	t.Helper()
+	var gotValue interface{}
+	if err := json.Unmarshal([]byte(got), &gotValue); err != nil {
+		t.Fatalf("%s: got invalid JSON %q: %v", name, got, err)
+	}
+	var wantValue interface{}
+	if err := json.Unmarshal([]byte(want), &wantValue); err != nil {
+		t.Fatalf("%s: test wanted invalid JSON %q: %v", name, want, err)
+	}
+
+	if !reflect.DeepEqual(gotValue, wantValue) {
+		t.Fatalf("%s: want JSON %s, got %s", name, want, got)
+	}
+}
+
+func assertQueryEqual(t *testing.T, raw string, want url.Values) {
+	t.Helper()
+	got, err := url.ParseQuery(raw)
+	if err != nil {
+		t.Fatalf("rawQuery: invalid query %q: %v", raw, err)
+	}
+
+	if !reflect.DeepEqual(got, want) {
+		t.Fatalf("rawQuery: want %v, got %v from %q", want, got, raw)
+	}
+}
+
+func countFDs(t *testing.T) int {
+	t.Helper()
+	entries, err := os.ReadDir("/proc/self/fd")
+	if err != nil {
+		t.Fatalf("read /proc/self/fd: %v", err)
+	}
+	return len(entries)
+}
+
+func newAliasTestClient(t *testing.T, handler http.HandlerFunc) (*elastic.Client, func()) {
+	t.Helper()
+	ts := httptest.NewServer(handler)
+	client, err := elastic.NewSimpleClient(elastic.SetURL(ts.URL))
+	if err != nil {
+		ts.Close()
+		t.Fatalf("NewSimpleClient: %v", err)
+	}
+	return client, ts.Close
+}
+
+func TestAliasActionBuildersSourceLiterals(t *testing.T) {
+
+
+	cases := []struct {
+		name string
+		got  string
+		want string
+	}{
+		{
+			name: "add single index",
+			got:  mustMarshalAction(t, elastic.NewAliasAddAction("alias1").Index("index1")),
+			want: `{"add":{"alias":"alias1","index":"index1"}}`,
+		},
+		{
+			name: "add two indices",
+			got:  mustMarshalAction(t, elastic.NewAliasAddAction("alias1").Index("index1", "index2")),
+			want: `{"add":{"alias":"alias1","indices":["index1","index2"]}}`,
+		},
+		{
+			name: "add filter",
+			got:  mustMarshalAction(t, elastic.NewAliasAddAction("alias1").Index("index1").Filter(elastic.NewTermQuery("user", "olivere"))),
+			want: `{"add":{"alias":"alias1","filter":{"term":{"user":"olivere"}},"index":"index1"}}`,
+		},
+		{
+			name: "add routing fields",
+			got:  mustMarshalAction(t, elastic.NewAliasAddAction("alias1").Index("index1").Routing("routing1").IndexRouting("indexRouting1").SearchRouting("r1", "r2").IsWriteIndex(false)),
+			want: `{"add":{"alias":"alias1","index":"index1","index_routing":"indexRouting1","is_write_index":false,"routing":"routing1","search_routing":"r1,r2"}}`,
+		},
+		{
+			name: "remove single index",
+			got:  mustMarshalAction(t, elastic.NewAliasRemoveAction("alias1").Index("index1")),
+			want: `{"remove":{"alias":"alias1","index":"index1"}}`,
+		},
+		{
+			name: "remove two indices",
+			got:  mustMarshalAction(t, elastic.NewAliasRemoveAction("alias1").Index("index1", "index2")),
+			want: `{"remove":{"alias":"alias1","indices":["index1","index2"]}}`,
+		},
+		{
+			name: "remove index",
+			got:  mustMarshalAction(t, elastic.NewAliasRemoveIndexAction("index1")),
+			want: `{"remove_index":{"index":"index1"}}`,
+		},
+	}
+	for _, tc := range cases {
+
+		assertJSONEqual(t, tc.name, tc.got, tc.want)
+	}
+}
+
+func TestAliasActionValidationErrors(t *testing.T) {
+
+
+	cases := []struct {
+		name string
+		err  error
+		want string
+	}{
+		{
+			name: "add missing both",
+			err:  elastic.NewAliasAddAction("").Validate(),
+			want: "missing required fields: [Alias Index]",
+		},
+		{
+			name: "add missing index",
+			err:  elastic.NewAliasAddAction("alias1").Validate(),
+			want: "missing required fields: [Index]",
+		},
+		{
+			name: "add missing alias",
+			err:  elastic.NewAliasAddAction("").Index("index1").Validate(),
+			want: "missing required fields: [Alias]",
+		},
+		{
+			name: "add write index with two indices",
+			err:  elastic.NewAliasAddAction("alias1").Index("index1", "index2").IsWriteIndex(true).Validate(),
+			want: "is_write_index",
+		},
+		{
+			name: "remove missing both",
+			err:  elastic.NewAliasRemoveAction("").Validate(),
+			want: "missing required fields: [Alias Index]",
+		},
+		{
+			name: "remove missing index",
+			err:  elastic.NewAliasRemoveAction("alias1").Validate(),
+			want: "missing required fields: [Index]",
+		},
+		{
+			name: "remove index missing index",
+			err:  elastic.NewAliasRemoveIndexAction("").Validate(),
+			want: "missing required field: index",
+		},
+	}
+	for _, tc := range cases {
+		if tc.err == nil {
+			t.Fatalf("%s: expected concrete error %q, got nil", tc.name, tc.want)
+		}
+		got := tc.err.Error()
+		switch tc.name {
+		case "add missing both", "remove missing both":
+
+			if !strings.Contains(got, "Alias") || !strings.Contains(got, "Index") {
+				t.Fatalf("%s: want error mentioning Alias and Index, got %q", tc.name, got)
+			}
+		case "add write index with two indices":
+
+			lower := strings.ToLower(got)
+			if !strings.Contains(lower, "is_write_index") || !strings.Contains(lower, "index") || !(strings.Contains(lower, "more") || strings.Contains(lower, "multiple")) {
+				t.Fatalf("%s: want explanatory is_write_index/multiple-index error, got %q", tc.name, got)
+			}
+		default:
+			if got != tc.want {
+				t.Fatalf("%s: want %q, got %q", tc.name, tc.want, got)
+			}
+		}
+	}
+}
+
+f

